B.agf={"restricted-exhaust-airflow":0,"clogged-lint-pathway":1,"thermal-fuse-open":2,"accessible-thermal-reset":3,"motor-overheat-protector-open":4,"heating-element-failed":5,"electric-supply-connection-fault":6,"broken-drive-belt":7,"worn-drum-rollers":8,"idler-pulley-wear":9,"door-switch-failure":10,"motor-failure":11}
B.a_4=s([u._,u.c,u.a,"Unplug the dryer (or switch off its breaker) before moving it.","Restore power, run a short heat cycle, and re-check exterior airflow."],t.s)
B.pq=s([B.mL,B.rx],t.c)
B.Sz=new A.ce("restricted-exhaust-airflow",u.dw,u.h0,B.a_4,B.j,B.pq,B.a2,!0,!0)
B.a0z=s(["Unplug the dryer before inspecting the lint housing.","Clean the lint filter and any safely accessible lint around the slot.","Do not dismantle sealed cabinets or wiring.","Restore power and run a small test load on a heat cycle."],t.s)
B.a0O=s([B.mL,B.rD],t.c)
B.SG=new A.ce("clogged-lint-pathway",u.gS,u.cR,B.a0z,B.j,B.a0O,B.a2,!0,!0)
